import{_ as e,a as o,o as a,a4 as r}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse('{"title":"Catalog Product — Copy","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-product-copy","title":"Copy a Catalog Product","description":"Duplicates an existing product across all attribute_values, images, inventories, categories and customer_group_prices. Refuses configurable variants. Mirrors Bagisto monolith `ProductController::copy`.","query":"curl -X POST \\"https://your-domain.com/api/admin/catalog/products/12/copy\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","variables":"{}\\n","response":"{\\n  \\"id\\": 43,\\n  \\"sourceId\\": 12,\\n  \\"sku\\": \\"SKU-001-copy-1\\",\\n  \\"type\\": \\"simple\\",\\n  \\"name\\": \\"Test SKU-001 (Copy)\\",\\n  \\"success\\": true,\\n  \\"message\\": \\"Product copied successfully.\\"\\n}\\n","commonErrors":[{"error":"Not Found (404)","cause":"Source product not found","solution":"Verify the `{sourceId}` exists in `products`"},{"error":"Unprocessable Entity (422)","cause":"Source product is a configurable variant (parent_id is set)","solution":"Copy the parent configurable, not the variant"},{"error":"Forbidden (403)","cause":"Admin role lacks `catalog.products.create`","solution":"Grant the permission to the admin role"}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/products/copy.md","filePath":"api/rest-api/admin/catalog/products/copy.md","lastUpdated":1784902076000}'),d={name:"api/rest-api/admin/catalog/products/copy.md"};function c(s,t,n,i,l,p){return a(),o("div",null,t[0]||(t[0]=[r('<h1 id="catalog-product-—-copy" tabindex="-1">Catalog Product — Copy <a class="header-anchor" href="#catalog-product-—-copy" aria-label="Permalink to &quot;Catalog Product — Copy&quot;">​</a></h1><p>Duplicates an existing catalog product. Fires <code>catalog.product.create.before</code> / <code>catalog.product.create.after</code> so listeners (search index, cache flush) trigger on the copy.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/products/{sourceId}/copy</code></td><td>POST</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>sourceId</code></td><td>integer</td><td>yes</td><td>ID of the product to duplicate.</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request body&quot;">​</a></h2><p>Empty. Send an empty JSON object <code>{}</code> if your client requires a body.</p><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>200 OK</code></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>ID of the newly created copy.</td></tr><tr><td><code>sourceId</code></td><td>integer</td><td>ID of the source product.</td></tr><tr><td><code>sku</code></td><td>string</td><td>Auto-suffixed SKU (Bagisto appends <code>-copy-N</code>).</td></tr><tr><td><code>type</code></td><td>string</td><td>Product type — matches the source.</td></tr><tr><td><code>name</code></td><td>string|null</td><td>Display name of the copy, when available.</td></tr><tr><td><code>success</code></td><td>bool</td><td>Always <code>true</code> on success.</td></tr><tr><td><code>message</code></td><td>string</td><td>Translated confirmation.</td></tr></tbody></table><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP</th><th>Cause</th></tr></thead><tbody><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid admin Bearer token.</td></tr><tr><td><code>403 Forbidden</code></td><td>Admin role lacks <code>catalog.products.create</code>.</td></tr><tr><td><code>404 Not Found</code></td><td>Source product not found.</td></tr><tr><td><code>422 Unprocessable Entity</code></td><td>Source is a configurable variant (<code>parent_id != null</code>).</td></tr><tr><td><code>500 Internal Server Error</code></td><td>Underlying copy threw an exception.</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The new SKU suffix is generated by Bagisto core — clients cannot pre-specify it.</li><li>Variant rows are NOT copy targets — only the parent configurable product is.</li></ul>',15)]))}const y=e(d,[["render",c]]);export{h as __pageData,y as default};
